// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.RingerModeimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Ringer Handler (Module 10 v2 — Step 10.3). * * Sets the device's ringer mode (NORMAL / VIBRATE / SILENT). * * ## Do Not Disturb access * * On Android 7+ (API 24+), switching to SILENT mode requires * `ACCESS_NOTIFICATION_POLICY` permission (Do Not Disturb access). Without * it, [android.media.AudioManager.setRingerMode] silently fails or throws * `SecurityException`. The handler catches the exception and returns a * user-friendly `Result.Failure(Permission.SpecialAccessRequired)`. * * ## Idempotent execution (Review 2 Elite 1) * * If the ringer is already in the target mode, skip the hardware call * (zero-flicker, battery save). * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous ringer mode. Undo restores the exact previous mode * — not the "inverse" (which is undefined for a 3-state enum). * * ## Resource category * * Ringer uses [ResourceCategory.AUDIO] — same as volume. Multiple ringer + * volume operations in a batch run sequentially to avoid AudioManager * contention. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture — Handler Interface Upgrade</a> */class RingerHandler(    private val audioService: AudioService,) : ReversibleHandler<SystemOperation.SetRingerMode> {    override val id: String = "ringer"    override val displayName: String = "Ringer Mode Control"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.AUDIO    override fun isAvailable(): Boolean = true  // all devices have AudioManager    override suspend fun execute(operation: SystemOperation.SetRingerMode): Result<Unit> =        HardwareExceptionMapper.withMappingSync("ringer") {            try {                audioService.setRingerMode(operation.mode)                Result.Success(Unit, CorrelationId.generate(), 0)            } catch (e: SecurityException) {                // DnD access required for SILENT mode on Android 7+.                Result.Failure(                    error = AppError.Permission.SpecialAccessRequired(                        settingsIntent = android.provider.Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS,                    ),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    override suspend fun capturePreState(operation: SystemOperation.SetRingerMode): Any? {        return try {            RingerPreState(previousMode = audioService.getRingerMode())        } catch (t: Throwable) {            Timber.tag("RingerHandler").w("Failed to capture pre-state", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetRingerMode, preState: Any?) {        if (preState !is RingerPreState) return        try {            audioService.setRingerMode(preState.previousMode)        } catch (t: Throwable) {            Timber.tag("RingerHandler").w("Failed to restore pre-state", t)        }    }    override suspend fun getCurrentState(): Any? = try {        RingerPreState(previousMode = audioService.getRingerMode())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetRingerMode): Boolean {        return try {            audioService.getRingerMode() == operation.mode        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetRingerMode): String =        when (operation.mode) {            RingerMode.NORMAL -> "Ringer set to normal"            RingerMode.VIBRATE -> "Ringer set to vibrate"            RingerMode.SILENT -> "Ringer set to silent"        }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is RingerPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"RingerPreState\",\"previousMode\":\"${preState.previousMode.name}\"}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "RingerPreState" -> RingerPreState(                previousMode = RingerMode.valueOf((map["previousMode"] as? String) ?: "NORMAL"),            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for ringer (previous mode). */    data class RingerPreState(val previousMode: RingerMode)}
